// Chỉ lấy bản final sau khi kỳ đã quay xong (từ 16:35 giờ VN).
const now = new Date();
const vnMinutes = (now.getUTCHours() * 60 + now.getUTCMinutes() + 7 * 60) % (24 * 60);
if (vnMinutes < 16 * 60 + 35) return [];
return [{ json: { station_code: 'DONG_NAI', product_code: 'xs-mn' } }];

// Nguồn authoritative: mỗi kỳ một request, Idempotency-Key cố định theo nội dung.
const src = $input.first().json;
const rows = Array.isArray(src.results) ? src.results : [src];
const out = [];
for (const row of rows) {
  if (!row.draw_date) continue;
  const prizes = {};
  for (const [code, numbers] of Object.entries(row.prizes ?? {})) {
    const list = (Array.isArray(numbers) ? numbers : [numbers])
      .map((n) => String(n).trim())
      .filter((n) => /^\d{2,6}$/.test(n));
    if (list.length > 0) prizes[code] = list;
  }
  if (Object.keys(prizes).length === 0) continue;
  const observation = {
    station_code: row.station_code ?? 'DONG_NAI',
    product_code: row.product_code ?? 'xs-mn',
    draw_date: row.draw_date,
    kind: 'final',
    source_id: 'src-official',
    period_code: row.period_code ?? null,
    prizes,
    observed_at: new Date().toISOString(),
    source_updated_at: row.updated_at ?? null,
  };
  const idem = `final:${observation.station_code}:${observation.product_code}:${observation.draw_date}:${JSON.stringify(prizes)}`.slice(0, 120);
  out.push({ json: { observation, idem } });
}
return out;

// Ghi log các trường hợp cần người xem: 409 (xung đột), 422 (payload sai), 423 (đang tắt xuất bản).
const rows = $input.all().map((item) => item.json);
const problems = rows.filter((row) => [409, 422, 423].includes(row.statusCode));
if (problems.length === 0) return [];
return problems.map((row) => ({ json: { statusCode: row.statusCode, body: row.body ?? row, at: new Date().toISOString() } }));
